INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cf61acbc-8627-5b07-b11c-06c6ecc68a83', 'UK Mandatory Climate-Related Financial Disclosures by Publicly Quoted Companies', 'Mandatory Climate-Related Financial Disclosures by Publicly Quoted Companies, Large Private Companies, and LLPs', 'This document outlines the UK’s regulatory framework mandating climate-related financial disclosures in alignment with the Task Force on Climate-related Financial Disclosures (TCFD). The requirements apply to publicly quoted companies, large private companies, and limited liability partnerships (LLPs) meeting specific thresholds. The regulations aim to improve transparency on climate risks and opportunities, enhancing informed decision-making for investors and stakeholders. Key aspects include governance arrangements, identification and management of climate-related risks and opportunities, integration into overall risk management processes, and disclosures on business impacts, targets, and key performance indicators. Applicable for financial years starting on or after April 6, 2022, the framework supports the UK’s Net Zero Strategy and complements existing reporting requirements like Streamlined Energy and Carbon Reporting (SECR).', 'This document outlines the UK’s regulatory framework mandating climate-related financial disclosures in alignment with the Task Force on Climate-related Financial Disclosures (TCFD). The requirements apply to publicly quoted companies, large private companies, and limited liability partnerships (LLPs) meeting specific thresholds. The regulations aim to improve transparency on climate risks and opportunities, enhancing informed decision-making for investors and stakeholders. Key aspects include governance arrangements, identification and management of climate-related risks and opportunities, integration into overall risk management processes, and disclosures on business impacts, targets, and key performance indicators. Applicable for financial years starting on or after April 6, 2022, the framework supports the UK’s Net Zero Strategy and complements existing reporting requirements like Streamlined Energy and Carbon Reporting (SECR).', 'This document outlines the UK’s regulatory framework mandating climate-related financial disclosures in alignment with the Task Force on Climate-related Financial Disclosures (TCFD). The requirements apply to publicly quoted companies, large private companies, and limited liability partnerships (LLPs) meeting specific thresholds. The regulations aim to improve transparency on climate risks and opportunities, enhancing informed decision-making for investors and stakeholders. Key aspects include governance arrangements, identification and management of climate-related risks and opportunities, integration into overall risk management processes, and disclosures on business impacts, targets, and key performance indicators. Applicable for financial years starting on or after April 6, 2022, the framework supports the UK’s Net Zero Strategy and complements existing reporting requirements like Streamlined Energy and Carbon Reporting (SECR).', 'UK', 'climate', 'in_force', '2022-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_102', ARRAY['sdg13', 'uk', 'sdg7', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42da95c1-9fed-56af-86ee-36fbf59a529c', 'UK Mandatory climate-related financial disclosures by publicly quoted companies', 'Mandatory climate-related financial disclosures by publicly quoted companies, large private companies and LLPs. Non-binding guidance', 'This document guides companies and LLPs on complying with new UK climate-related financial disclosure laws effective from April 2022, offering a factual explanation rather than exhaustive legal advice, issued by the Secretary of State for Business, Energy and Industrial Strategy.', 'This document guides companies and LLPs on complying with new UK climate-related financial disclosure laws effective from April 2022, offering a factual explanation rather than exhaustive legal advice, issued by the Secretary of State for Business, Energy and Industrial Strategy.', 'This document guides companies and LLPs on complying with new UK climate-related financial disclosure laws effective from April 2022, offering a factual explanation rather than exhaustive legal advice, issued by the Secretary of State for Business, Energy and Industrial Strategy.', 'UK', 'climate', 'in_force', '2022-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_106', ARRAY['guidance_frameworks', 'sdg13', 'uk', 'sdg7', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d9dab1ca-2bf0-56ce-b40c-ac0b5fc7cc4b', 'UK Companies (Strategic Report) (Climate-related Financial Disclosure) Regulations', 'The Companies (Strategic Report) (Climate-related Financial Disclosure) Regulations', 'These regulations, which came into force on April 6, 2022, amend the Companies Act 2006 to introduce mandatory climate-related financial disclosures for large UK companies. The legislation aligns with the Task Force on Climate-related Financial Disclosures (TCFD) recommendations, ensuring businesses assess and disclose their exposure to climate risks.

Key provisions include:

Scope of Companies Covered:
Traded companies, banking companies, and insurance firms.
Large private companies with more than 500 employees and £500 million+ turnover.
Climate-Related Financial Disclosure Requirements:
Governance: How the company oversees climate-related risks and opportunities.
Risk Management: How climate risks are identified, assessed, and managed.
Strategy: The impact of climate-related risks on business models and financial planning.
Metrics & Targets: Performance against set climate-related targets, including emissions reductions.
Integration into Strategic Reports:
Disclosures must be part of the company’s Strategic Report, ensuring alignment with financial performance and business planning.
Review and Compliance:
The Secretary of State must review the regulations before April 6, 2027, with further reviews every five years.
Companies that fail to comply could face regulatory scrutiny and reputational risks.
These regulations reinforce corporate climate accountability, improve investor confidence, and align the UK with global ESG disclosure standards.', 'These regulations, which came into force on April 6, 2022, amend the Companies Act 2006 to introduce mandatory climate-related financial disclosures for large UK companies. The legislation aligns with the Task Force on Climate-related Financial Disclosures (TCFD) recommendations, ensuring businesses assess and disclose their exposure to climate risks.

