INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7ed4380a-4035-5a93-9531-6e8afa2ad7ab', 'UK Audit firm Governance Code. Revised', 'Audit firm Governance Code. Revised 2022', 'The Audit Firm Governance Code (“the Code”) was first published in January 2010.  At that time, the Code applied to audit firms (“firms”) auditing 20 or more listed companies. It introduced for the first time the concept of independent non-executives (“INEs”) in firms. INEs are now well established in all of the firms currently applying the Code. The flexibility allowed by ‘comply or explain’ provisions remains an important characteristic of the Code. The Code was first updated by the FRC in 2016 following a high-level review of its implementation by those audit firms within its scope. It has been updated again in 2022 to take account of the introduction of operational separation of audit practices at the largest audit firms and findings from the FRC’s review of firm implementation against the 2016 Code. The threshold for application of the 2022 Code has been aligned with the rest of the regulatory regime for audit which is based on the audit of public interest entities (“PIEs”) rather than listed companies. The Code applies to the firm as a whole, not purely the audit practice. It continues to apply in its entirety in firms where the audit practice is operationally-separate from the rest of the firm.', 'The Audit Firm Governance Code (“the Code”) was first published in January 2010.  At that time, the Code applied to audit firms (“firms”) auditing 20 or more listed companies. It introduced for the first time the concept of independent non-executives (“INEs”) in firms. INEs are now well established in all of the firms currently applying the Code. The flexibility allowed by ‘comply or explain’ provisions remains an important characteristic of the Code. The Code was first updated by the FRC in 2016 following a high-level review of its implementation by those audit firms within its scope. It has been updated again in 2022 to take account of the introduction of operational separation of audit practices at the largest audit firms and findings from the FRC’s review of firm implementation against the 2016 Code. The threshold for application of the 2022 Code has been aligned with the rest of the regulatory regime for audit which is based on the audit of public interest entities (“PIEs”) rather than listed companies. The Code applies to the firm as a whole, not purely the audit practice. It continues to apply in its entirety in firms where the audit practice is operationally-separate from the rest of the firm.', 'The Audit Firm Governance Code (“the Code”) was first published in January 2010.  At that time, the Code applied to audit firms (“firms”) auditing 20 or more listed companies. It introduced for the first time the concept of independent non-executives (“INEs”) in firms. INEs are now well established in all of the firms currently applying the Code. The flexibility allowed by ‘comply or explain’ provisions remains an important characteristic of the Code. The Code was first updated by the FRC in 2016 following a high-level review of its implementation by those audit firms within its scope. It has been updated again in 2022 to take account of the introduction of operational separation of audit practices at the largest audit firms and findings from the FRC’s review of firm implementation against the 2016 Code. The threshold for application of the 2022 Code has been aligned with the rest of the regulatory regime for audit which is based on the audit of public interest entities (“PIEs”) rather than listed companies. The Code applies to the firm as a whole, not purely the audit practice. It continues to apply in its entirety in firms where the audit practice is operationally-separate from the rest of the firm.', 'UK', 'climate', 'in_force', '2022-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_98', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ac8ea3ee-ec37-5476-9d89-d1c77569b72f', 'UK Your guide to climate reporting: Guidance for London-listed', 'Your guide to climate reporting: Guidance for London-listed companies on the integration of climate reporting best practice and TCFD implementation', 'The London Stock Exchange published a guide in 2021 to provide guidance for London-listed companies on integrating climate reporting best practices and implementing the recommendations of the Task Force on Climate-related Financial Disclosures (TCFD). The guide highlights the importance of climate reporting as a means of enabling investors to understand a company''s exposure to climate-related risks and opportunities. It outlines the key components of effective climate reporting, including the identification and assessment of climate risks and opportunities, the setting of targets and strategies for climate action, and the disclosure of relevant data and metrics. The guide also provides a step-by-step approach for companies to implement the TCFD recommendations, which includes assessing climate-related risks and opportunities, developing climate-related metrics, and reporting on climate-related risks and opportunities in mainstream company reports. Additionally, the guide emphasizes the importance of engagement with stakeholders, including investors, to ensure that climate reporting is aligned with their expectations and needs. It also encourages companies to seek external assurance of their climate reporting to enhance credibility and transparency.', 'The London Stock Exchange published a guide in 2021 to provide guidance for London-listed companies on integrating climate reporting best practices and implementing the recommendations of the Task Force on Climate-related Financial Disclosures (TCFD). The guide highlights the importance of climate reporting as a means of enabling investors to understand a company''s exposure to climate-related risks and opportunities. It outlines the key components of effective climate reporting, including the identification and assessment of climate risks and opportunities, the setting of targets and strategies for climate action, and the disclosure of relevant data and metrics. The guide also provides a step-by-step approach for companies to implement the TCFD recommendations, which includes assessing climate-related risks and opportunities, developing climate-related metrics, and reporting on climate-related risks and opportunities in mainstream company reports. Additionally, the guide emphasizes the importance of engagement with stakeholders, including investors, to ensure that climate reporting is aligned with their expectations and needs. It also encourages companies to seek external assurance of their climate reporting to enhance credibility and transparency.', 'The London Stock Exchange published a guide in 2021 to provide guidance for London-listed companies on integrating climate reporting best practices and implementing the recommendations of the Task Force on Climate-related Financial Disclosures (TCFD). The guide highlights the importance of climate reporting as a means of enabling investors to understand a company''s exposure to climate-related risks and opportunities. It outlines the key components of effective climate reporting, including the identification and assessment of climate risks and opportunities, the setting of targets and strategies for climate action, and the disclosure of relevant data and metrics. The guide also provides a step-by-step approach for companies to implement the TCFD recommendations, which includes assessing climate-related risks and opportunities, developing climate-related metrics, and reporting on climate-related risks and opportunities in mainstream company reports. Additionally, the guide emphasizes the importance of engagement with stakeholders, including investors, to ensure that climate reporting is aligned with their expectations and needs. It also encourages companies to seek external assurance of their climate reporting to enhance credibility and transparency.', 'UK', 'climate', 'in_force', '2021-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_103', ARRAY['sdg13', 'uk', 'regulations', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3b56a858-42e7-5e7c-9c8a-4dbf842a15fd', 'UK Greening Finance: A Roadmap to Sustainable Investing', 'Greening Finance: A Roadmap to Sustainable Investing, 2021', '‘Greening Finance: A Roadmap to Sustainable Investing’ sets out the government’s long-term ambition to green the financial system and align it with the UK’s world-leading net-zero commitment.', '‘Greening Finance: A Roadmap to Sustainable Investing’ sets out the government’s long-term ambition to green the financial system and align it with the UK’s world-leading net-zero commitment.', '‘Greening Finance: A Roadmap to Sustainable Investing’ sets out the government’s long-term ambition to green the financial system and align it with the UK’s world-leading net-zero commitment.', 'UK', 'climate', 'in_force', '2021-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_75', ARRAY['sdg13', 'uk', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('169a378a-3a7f-553b-ac4b-a6dfd5effb77', 'UK Environment Act', 'Environment Act 2021', 'The Environment Act 2021 in the United Kingdom focuses on enhancing environmental governance, setting specific targets for improvement, establishing the Office for Environmental Protection, and addressing waste and resource efficiency. It targets government entities, producers, and the general public to promote environmental protection and sustainability.', 'The Environment Act 2021 in the United Kingdom focuses on enhancing environmental governance, setting specific targets for improvement, establishing the Office for Environmental Protection, and addressing waste and resource efficiency. It targets government entities, producers, and the general public to promote environmental protection and sustainability.', 'The Environment Act 2021 in the United Kingdom focuses on enhancing environmental governance, setting specific targets for improvement, establishing the Office for Environmental Protection, and addressing waste and resource efficiency. It targets government entities, producers, and the general public to promote environmental protection and sustainability.', 'UK', 'circularity', 'in_force', '2021-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_122', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e6a815b6-344e-5061-ad18-3fc010689338', 'UK Procurement Policy Note – Taking Account of Carbon', 'Procurement Policy Note – Taking Account of Carbon Reduction Plans in the procurement of major government contracts', 'The UK''s Procurement Policy Note requires government departments to consider suppliers'' Net Zero Carbon Reduction Plans in major contracts over £5 million per annum. Organizations must apply this policy to procurements advertised after September 30, 2021, ensuring suppliers commit to achieving Net Zero emissions by 2050. Target audience: Central Government Departments, Executive Agencies, and Public Bodies.', 'The UK''s Procurement Policy Note requires government departments to consider suppliers'' Net Zero Carbon Reduction Plans in major contracts over £5 million per annum. Organizations must apply this policy to procurements advertised after September 30, 2021, ensuring suppliers commit to achieving Net Zero emissions by 2050. Target audience: Central Government Departments, Executive Agencies, and Public Bodies.', 'The UK''s Procurement Policy Note requires government departments to consider suppliers'' Net Zero Carbon Reduction Plans in major contracts over £5 million per annum. Organizations must apply this policy to procurements advertised after September 30, 2021, ensuring suppliers commit to achieving Net Zero emissions by 2050. Target audience: Central Government Departments, Executive Agencies, and Public Bodies.', 'UK', 'climate', 'in_force', '2021-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_123', ARRAY['sdg13', 'uk', 'regulations', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('04de44eb-7689-52f0-a1a3-06305d5b717a', 'UK adopting and applying the PPN – Selection Criteria', 'Guidance on adopting and applying the PPN 06/21 – Selection Criteria', 'The UK guidance on PPN 06/21 – Selection Criteria supports the Net Zero target by assessing suppliers'' carbon reduction plans for relevant contracts. It details exclusion criteria, self-declaration questions, and assessment methodology, targeting In-Scope Organizations procuring contracts subject to specific regulations.', 'The UK guidance on PPN 06/21 – Selection Criteria supports the Net Zero target by assessing suppliers'' carbon reduction plans for relevant contracts. It details exclusion criteria, self-declaration questions, and assessment methodology, targeting In-Scope Organizations procuring contracts subject to specific regulations.', 'The UK guidance on PPN 06/21 – Selection Criteria supports the Net Zero target by assessing suppliers'' carbon reduction plans for relevant contracts. It details exclusion criteria, self-declaration questions, and assessment methodology, targeting In-Scope Organizations procuring contracts subject to specific regulations.', 'UK', 'climate', 'in_force', '2021-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_124', ARRAY['guidance_frameworks', 'mandatory', 'sdg13', 'uk']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f46f3a07-bd6f-59c5-8c5d-7ec93efb78a4', 'UK Technical standard for Completion of Carbon Reduction Plans', 'Technical standard for Completion of Carbon Reduction Plans', 'The UK''s Technical Standard for Completion of Carbon Reduction Plans outlines requirements for suppliers to report and reduce carbon emissions in line with Net Zero by 2050 commitment. Key elements include reporting guidelines for various emission scopes and annual updates for transparency, targeting suppliers responding to central Government contracts.', 'The UK''s Technical Standard for Completion of Carbon Reduction Plans outlines requirements for suppliers to report and reduce carbon emissions in line with Net Zero by 2050 commitment. Key elements include reporting guidelines for various emission scopes and annual updates for transparency, targeting suppliers responding to central Government contracts.', 'The UK''s Technical Standard for Completion of Carbon Reduction Plans outlines requirements for suppliers to report and reduce carbon emissions in line with Net Zero by 2050 commitment. Key elements include reporting guidelines for various emission scopes and annual updates for transparency, targeting suppliers responding to central Government contracts.', 'UK', 'climate', 'in_force', '2021-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/185_125', ARRAY['sdg13', 'voluntary_frameworks', 'uk', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a41ba6b6-26cc-5883-9992-8cfdfd5b54b1', 'UK Sustainability Reporting Standard for Social Housing. The Final', 'The Sustainability Reporting Standard for Social Housing. The Final Report of the ESG Social Housing Working Group', 'The Standard is a voluntary disclosure framework for housing providers to report on their Environmental, Social and Governance (ESG) performance in a transparent, consistent and comparable way.', 'The Standard is a voluntary disclosure framework for housing providers to report on their Environmental, Social and Governance (ESG) performance in a transparent, consistent and comparable way.', 'The Standard is a voluntary disclosure framework for housing providers to report on their Environmental, Social and Governance (ESG) performance in a transparent, consistent and comparable way.', 'UK', 'climate', 'in_force', '2020-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_110', ARRAY['uk', 'sdg11', 'voluntary', 'sdg16', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46798712-33dc-53ae-82f6-39f9fee4e101', 'UK Stewardship Code', 'The UK Stewardship Code', 'The UK Stewardship Code 2020, published by the Financial Reporting Council (FRC), sets standards for responsible investment stewardship. It is applicable to asset owners, asset managers, and service providers involved in the allocation and oversight of capital. The Code outlines principles designed to promote transparency, governance, and accountability, aiming to create long-term value for clients, beneficiaries, and society. Its key areas of focus include purpose and governance, investment approach, engagement, and the exercising of rights and responsibilities. Signatories are expected to adopt and explain how they align with these principles through clear, outcome-driven stewardship reports. The Code emphasizes integration of environmental, social, and governance (ESG) factors, collaboration, and active participation in financial market improvement. Although voluntary, compliance with the Code is encouraged by regulatory requirements such as the FCA’s Conduct of Business Sourcebook and pension regulations.', 'The UK Stewardship Code 2020, published by the Financial Reporting Council (FRC), sets standards for responsible investment stewardship. It is applicable to asset owners, asset managers, and service providers involved in the allocation and oversight of capital. The Code outlines principles designed to promote transparency, governance, and accountability, aiming to create long-term value for clients, beneficiaries, and society. Its key areas of focus include purpose and governance, investment approach, engagement, and the exercising of rights and responsibilities. Signatories are expected to adopt and explain how they align with these principles through clear, outcome-driven stewardship reports. The Code emphasizes integration of environmental, social, and governance (ESG) factors, collaboration, and active participation in financial market improvement. Although voluntary, compliance with the Code is encouraged by regulatory requirements such as the FCA’s Conduct of Business Sourcebook and pension regulations.', 'The UK Stewardship Code 2020, published by the Financial Reporting Council (FRC), sets standards for responsible investment stewardship. It is applicable to asset owners, asset managers, and service providers involved in the allocation and oversight of capital. The Code outlines principles designed to promote transparency, governance, and accountability, aiming to create long-term value for clients, beneficiaries, and society. Its key areas of focus include purpose and governance, investment approach, engagement, and the exercising of rights and responsibilities. Signatories are expected to adopt and explain how they align with these principles through clear, outcome-driven stewardship reports. The Code emphasizes integration of environmental, social, and governance (ESG) factors, collaboration, and active participation in financial market improvement. Although voluntary, compliance with the Code is encouraged by regulatory requirements such as the FCA’s Conduct of Business Sourcebook and pension regulations.', 'UK', 'climate', 'in_force', '2020-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_74', ARRAY['sdg8', 'sdg13', 'uk', 'sdg7', 'regulations', 'sdg17', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a08e71c2-094d-5e0e-b696-e34b3d0fa7de', 'UK Green Climate Fund Proposal Toolkit 2020. Toolkit', 'Green Climate Fund Proposal Toolkit 2020. Toolkit to develop a project proposal for the GCF', 'This guide integrates the latest GCF policy changes and funding proposal template version 2.0 in order to provide the most recent guidance to project proponents, accredited entities and national designated authorities and help them to navigate the ever-changing GCF project requirements.', 'This guide integrates the latest GCF policy changes and funding proposal template version 2.0 in order to provide the most recent guidance to project proponents, accredited entities and national designated authorities and help them to navigate the ever-changing GCF project requirements.', 'This guide integrates the latest GCF policy changes and funding proposal template version 2.0 in order to provide the most recent guidance to project proponents, accredited entities and national designated authorities and help them to navigate the ever-changing GCF project requirements.', 'UK', 'climate', 'in_force', '2020-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_93', ARRAY['guidance_frameworks', 'sdg13', 'uk', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0e097090-93c4-59fb-b30f-44c424fdec3f', 'UK Revealing the full picture. Your guide to ESG', 'Revealing the full picture. Your guide to ESG reporting, 2020', 'London Stock Exchange Group has issued this guidance, setting out recommendations for good practice in Environmental, Social and Governance reporting (ESG). The global guide responds to demand from investors for a more consistent approach to ESG reporting, which is now a core part of the investment decision process.', 'London Stock Exchange Group has issued this guidance, setting out recommendations for good practice in Environmental, Social and Governance reporting (ESG). The global guide responds to demand from investors for a more consistent approach to ESG reporting, which is now a core part of the investment decision process.', 'London Stock Exchange Group has issued this guidance, setting out recommendations for good practice in Environmental, Social and Governance reporting (ESG). The global guide responds to demand from investors for a more consistent approach to ESG reporting, which is now a core part of the investment decision process.', 'UK', 'climate', 'in_force', '2020-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_94', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9f9b77a8-6889-5e76-9820-fdde52467534', 'UK Environmental Reporting Guidelines: Including Streamlined Energy and Carbon', 'Environmental Reporting Guidelines: Including Streamlined Energy and Carbon Reporting Guidance', 'These guidelines provide a framework for UK companies and limited liability partnerships (LLPs) to meet reporting requirements under the Companies Act 2006 and the Companies (Directors’ Report) and LLP (Energy and Carbon Report) Regulations 2018. They outline the steps for determining environmental impacts, data collection, and reporting. Aimed at improving transparency, the guidance mandates that quoted companies disclose global GHG emissions and energy use in annual reports. Large unquoted companies and LLPs must report UK-specific energy usage, GHG emissions, intensity ratios, and energy efficiency measures. The guidelines encourage the integration of environmental reporting into broader financial and sustainability strategies, enabling businesses to demonstrate leadership, comply with legal obligations, and achieve resource efficiency.', 'These guidelines provide a framework for UK companies and limited liability partnerships (LLPs) to meet reporting requirements under the Companies Act 2006 and the Companies (Directors’ Report) and LLP (Energy and Carbon Report) Regulations 2018. They outline the steps for determining environmental impacts, data collection, and reporting. Aimed at improving transparency, the guidance mandates that quoted companies disclose global GHG emissions and energy use in annual reports. Large unquoted companies and LLPs must report UK-specific energy usage, GHG emissions, intensity ratios, and energy efficiency measures. The guidelines encourage the integration of environmental reporting into broader financial and sustainability strategies, enabling businesses to demonstrate leadership, comply with legal obligations, and achieve resource efficiency.', 'These guidelines provide a framework for UK companies and limited liability partnerships (LLPs) to meet reporting requirements under the Companies Act 2006 and the Companies (Directors’ Report) and LLP (Energy and Carbon Report) Regulations 2018. They outline the steps for determining environmental impacts, data collection, and reporting. Aimed at improving transparency, the guidance mandates that quoted companies disclose global GHG emissions and energy use in annual reports. Large unquoted companies and LLPs must report UK-specific energy usage, GHG emissions, intensity ratios, and energy efficiency measures. The guidelines encourage the integration of environmental reporting into broader financial and sustainability strategies, enabling businesses to demonstrate leadership, comply with legal obligations, and achieve resource efficiency.', 'UK', 'climate', 'in_force', '2019-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_11', ARRAY['guidance_frameworks', 'sdg13', 'uk', 'sdg7', 'sdg17', 'sdg16', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5c500dda-ab39-501c-92ee-d6c7474cdd79', 'UK Proposals to promote shareholder engagement: Feedback to CP19/7', 'Proposals to promote shareholder engagement: Feedback to CP19/7 and final rules', 'This Policy Statement (PS) follows our Consultation Paper Consultation on proposals to improve shareholder engagement (CP19/7). It summarises the feedback we received to the consultation, which closed on 27 March, and our response to it. It also sets out the final rules. CP19/7 set out our proposals to implement requirements of the revised Shareholder Rights Directive (SRD II) as they apply to life insurers and asset managers that we regulate, and to issuers in respect of certain transactions they enter into with a related party (Related Party Transactions or RPTs).', 'This Policy Statement (PS) follows our Consultation Paper Consultation on proposals to improve shareholder engagement (CP19/7). It summarises the feedback we received to the consultation, which closed on 27 March, and our response to it. It also sets out the final rules. CP19/7 set out our proposals to implement requirements of the revised Shareholder Rights Directive (SRD II) as they apply to life insurers and asset managers that we regulate, and to issuers in respect of certain transactions they enter into with a related party (Related Party Transactions or RPTs).', 'This Policy Statement (PS) follows our Consultation Paper Consultation on proposals to improve shareholder engagement (CP19/7). It summarises the feedback we received to the consultation, which closed on 27 March, and our response to it. It also sets out the final rules. CP19/7 set out our proposals to implement requirements of the revised Shareholder Rights Directive (SRD II) as they apply to life insurers and asset managers that we regulate, and to issuers in respect of certain transactions they enter into with a related party (Related Party Transactions or RPTs).', 'UK', 'governance', 'in_force', '2019-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_24', ARRAY['disclosure', 'mandatory', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('151645fd-4240-53ec-95c2-fcf6cd2e8fa5', 'UK Supervisory Statement : Enhancing banks'' and insurers'' approaches', 'Supervisory Statement 3/19: Enhancing banks'' and insurers'' approaches to managing the financial risk from climate change', 'This supervisory statement (SS) is relevant to all UK insurance and reinsurance firms and groups, ie those within the scope of Solvency II including the Society of Lloyd’s and managing agents (‘Solvency II firms’) and non-Solvency II firms, (collectively referred to as ‘insurers’), banks, building societies, and Prudential Regulation Authority (PRA) designated investment firms (collectively referred to as ‘banks’). ‘Firms’ will be used to refer to both insurers and banks. Climate change, and society’s response to it, present financial risks which are relevant to the PRA’s objectives. While the financial risks from climate change may crystallise in full over longer time horizons, they are also becoming apparent now.  The PRA’s reviews of current practice in the banking and insurance sectors have highlighted that, while firms are enhancing their approaches to managing the financial risks from climate change, few firms are taking a strategic approach that considers how actions today affect future financial risks.', 'This supervisory statement (SS) is relevant to all UK insurance and reinsurance firms and groups, ie those within the scope of Solvency II including the Society of Lloyd’s and managing agents (‘Solvency II firms’) and non-Solvency II firms, (collectively referred to as ‘insurers’), banks, building societies, and Prudential Regulation Authority (PRA) designated investment firms (collectively referred to as ‘banks’). ‘Firms’ will be used to refer to both insurers and banks. Climate change, and society’s response to it, present financial risks which are relevant to the PRA’s objectives. While the financial risks from climate change may crystallise in full over longer time horizons, they are also becoming apparent now.  The PRA’s reviews of current practice in the banking and insurance sectors have highlighted that, while firms are enhancing their approaches to managing the financial risks from climate change, few firms are taking a strategic approach that considers how actions today affect future financial risks.', 'This supervisory statement (SS) is relevant to all UK insurance and reinsurance firms and groups, ie those within the scope of Solvency II including the Society of Lloyd’s and managing agents (‘Solvency II firms’) and non-Solvency II firms, (collectively referred to as ‘insurers’), banks, building societies, and Prudential Regulation Authority (PRA) designated investment firms (collectively referred to as ‘banks’). ‘Firms’ will be used to refer to both insurers and banks. Climate change, and society’s response to it, present financial risks which are relevant to the PRA’s objectives. While the financial risks from climate change may crystallise in full over longer time horizons, they are also becoming apparent now.  The PRA’s reviews of current practice in the banking and insurance sectors have highlighted that, while firms are enhancing their approaches to managing the financial risks from climate change, few firms are taking a strategic approach that considers how actions today affect future financial risks.', 'UK', 'climate', 'in_force', '2019-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_25', ARRAY['sdg13', 'uk', 'regulations', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ea3dca4-7643-53cd-9459-c3557deffef8', 'UK Green Finance Strategy: Transforming Finance for a Greener', 'Green Finance Strategy: Transforming Finance for a Greener Future', 'The UK’s Green Finance Strategy outlines a comprehensive approach to aligning private and public sector financial flows with the objectives of achieving net-zero emissions by 2050 and fostering environmentally sustainable growth. The strategy is built around three pillars: Greening Finance, Financing Green, and Capturing the Opportunity. Key measures include integrating climate-related risks into financial decision-making, promoting adoption of TCFD-aligned disclosures, and supporting innovative green financial products and services. The strategy also emphasizes building a robust domestic market for green finance, enhancing global leadership through the Green Finance Institute, and ensuring the UK''s financial system supports a resilient, low-carbon transition. Collaboration with regulators, private sector stakeholders, and international partners is central to delivering the systemic changes required to meet these goals.', 'The UK’s Green Finance Strategy outlines a comprehensive approach to aligning private and public sector financial flows with the objectives of achieving net-zero emissions by 2050 and fostering environmentally sustainable growth. The strategy is built around three pillars: Greening Finance, Financing Green, and Capturing the Opportunity. Key measures include integrating climate-related risks into financial decision-making, promoting adoption of TCFD-aligned disclosures, and supporting innovative green financial products and services. The strategy also emphasizes building a robust domestic market for green finance, enhancing global leadership through the Green Finance Institute, and ensuring the UK''s financial system supports a resilient, low-carbon transition. Collaboration with regulators, private sector stakeholders, and international partners is central to delivering the systemic changes required to meet these goals.', 'The UK’s Green Finance Strategy outlines a comprehensive approach to aligning private and public sector financial flows with the objectives of achieving net-zero emissions by 2050 and fostering environmentally sustainable growth. The strategy is built around three pillars: Greening Finance, Financing Green, and Capturing the Opportunity. Key measures include integrating climate-related risks into financial decision-making, promoting adoption of TCFD-aligned disclosures, and supporting innovative green financial products and services. The strategy also emphasizes building a robust domestic market for green finance, enhancing global leadership through the Green Finance Institute, and ensuring the UK''s financial system supports a resilient, low-carbon transition. Collaboration with regulators, private sector stakeholders, and international partners is central to delivering the systemic changes required to meet these goals.', 'UK', 'climate', 'in_force', '2019-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_73', ARRAY['sdg13', 'uk', 'sdg7', 'sdg17', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1e625c4b-dc95-5947-8fb8-76d8a0256aff', 'UK Prudential Regulation Authority (PRA) Supervisory Statement SS3/19 –', 'The Prudential Regulation Authority (PRA) Supervisory Statement SS3/19 – Enhancing Banks’ and Insurers’ Approaches to Managing the Financial Risks from Climate Change.', 'Issued by the Bank of England’s Prudential Regulation Authority (PRA) in April 2019, this Supervisory Statement (SS3/19) outlines expectations for UK banks and insurers regarding climate-related financial risk management. It requires financial institutions to integrate climate risk into governance, risk management, scenario analysis, and disclosure processes.

Key provisions include:

Scope & Applicability:
Applies to UK insurers (Solvency II and non-Solvency II firms), banks, building societies, and PRA-designated investment firms.
Climate-Related Financial Risks:
Physical risks: Damages from climate-related events (e.g., floods, storms).
Transition risks: Financial losses from transitioning to a low-carbon economy.
Liability risks: Legal claims from stakeholders affected by climate impacts.
Strategic Risk Management Approach:
Boards must embed climate-related risks into governance arrangements.
Firms must integrate climate risks into financial risk management frameworks.
Scenario analysis and stress testing are required to assess climate risks.
Banks and insurers must develop disclosure frameworks for climate-related financial risks.
Disclosure Requirements:
Firms must provide transparency on how climate risks impact their business models, risk exposures, and capital adequacy.
Encourages alignment with Task Force on Climate-related Financial Disclosures (TCFD) recommendations.
Supports consistency with Capital Requirements Regulation (CRR) and Solvency II.
The SS3/19 framework strengthens the resilience of financial institutions against climate risks, ensuring long-term financial stability and regulatory alignment with global climate disclosure standards.', 'Issued by the Bank of England’s Prudential Regulation Authority (PRA) in April 2019, this Supervisory Statement (SS3/19) outlines expectations for UK banks and insurers regarding climate-related financial risk management. It requires financial institutions to integrate climate risk into governance, risk management, scenario analysis, and disclosure processes.

