INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dd4d9e5b-4d98-5c9d-ae29-f07593c0b0f0', 'UK Co-operative Corporate Governance Code', 'Co-operative Corporate Governance Code, 2019', 'This code is a tool to help chart what good practice can look like. It focuses on best practice around democracy and quality of leadership that emerges through good governance.', 'This code is a tool to help chart what good practice can look like. It focuses on best practice around democracy and quality of leadership that emerges through good governance.', 'This code is a tool to help chart what good practice can look like. It focuses on best practice around democracy and quality of leadership that emerges through good governance.', 'UK', 'governance', 'in_force', '2019-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_92', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('033bbc97-0e8f-51e1-8a04-ea9d81ae68cc', 'UK Your guide to ESG reporting. Guidance for issuers', 'Your guide to ESG reporting. Guidance for issuers on the integration of ESG into investor reporting and communication, 2018', 'The guidance is to help companies gain a clear understanding of what ESG information they should disclose and how. It is a tool for LSEG listed companies to improve their transparency, especially for investors to make better informed company engagement and investment decisions.', 'The guidance is to help companies gain a clear understanding of what ESG information they should disclose and how. It is a tool for LSEG listed companies to improve their transparency, especially for investors to make better informed company engagement and investment decisions.', 'The guidance is to help companies gain a clear understanding of what ESG information they should disclose and how. It is a tool for LSEG listed companies to improve their transparency, especially for investors to make better informed company engagement and investment decisions.', 'UK', 'climate', 'in_force', '2018-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_16', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('90d1bd9a-a4ee-58f5-b12c-1b373ff20d4e', 'UK Clean Growth Strategy. Leading the way to a', 'The Clean Growth Strategy. Leading the way to a low carbon future, 2018', 'This strategy sets out our proposals for decarbonising all sectors of the UK economy through the 2020s. It explains how the whole country can benefit from low carbon opportunities, while meeting national and international commitments to tackle climate change.', 'This strategy sets out our proposals for decarbonising all sectors of the UK economy through the 2020s. It explains how the whole country can benefit from low carbon opportunities, while meeting national and international commitments to tackle climate change.', 'This strategy sets out our proposals for decarbonising all sectors of the UK economy through the 2020s. It explains how the whole country can benefit from low carbon opportunities, while meeting national and international commitments to tackle climate change.', 'UK', 'climate', 'in_force', '2018-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_21', ARRAY['sdg13', 'uk', 'sdg7', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ac0fd3b-5860-5132-b0f2-67e013786961', 'UK Pension Protection Fund (Pensionable Service) and Occupational Pension', 'The Pension Protection Fund (Pensionable Service) and Occupational Pension Schemes (Investment and Disclosure) (Amendment and Modification) Regulations 2018', 'The amended Act places a statutory duty on scheme auditors to report breaches of the law, commonly referred to as ‘whistleblowing’, to the Pensions Regulator as soon as reasonably practicable.', 'The amended Act places a statutory duty on scheme auditors to report breaches of the law, commonly referred to as ‘whistleblowing’, to the Pensions Regulator as soon as reasonably practicable.', 'The amended Act places a statutory duty on scheme auditors to report breaches of the law, commonly referred to as ‘whistleblowing’, to the Pensions Regulator as soon as reasonably practicable.', 'UK', 'climate', 'in_force', '2018-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_27', ARRAY['sdg8', 'uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('afbe6e26-4735-533a-8345-59a7fe976814', 'UK Companies (Directors’ Report) and Limited Liability Partnerships (Energy', 'The Companies (Directors’ Report) and Limited Liability Partnerships (Energy and Carbon Report) Regulations', 'These regulations, which came into force on April 1, 2019, amend UK company law to enhance corporate energy and carbon reporting requirements. They introduce mandatory energy consumption and emissions disclosures for certain companies and limited liability partnerships (LLPs), aligning with climate and sustainability objectives.

Key provisions include:

Scope of Companies Covered:
Quoted companies (i.e., listed companies).
Large unquoted companies and large LLPs (meeting two or more of: £36M+ turnover, £18M+ balance sheet, 250+ employees).
Energy & Carbon Reporting Obligations:
Companies must report annual greenhouse gas (GHG) emissions, total energy consumption, and energy efficiency actions taken.
Reports must include kWh energy use, carbon footprint, and emissions intensity metrics.
Directors’ Report & Carbon Disclosures:
Required to be part of directors’ reports for companies and energy and carbon reports for LLPs.
Group reporting is allowed if disclosures cover all relevant subsidiaries.
Exemptions & Penalties:
Companies using less than 40,000 kWh annually are exempt.
Failure to comply results in financial penalties and legal liability for directors.
Alignment with International Standards:
Methodologies must align with GHG Protocol, ISO 14064, or government guidelines.
Companies must ensure year-on-year comparability in reporting.
These regulations reinforce corporate climate accountability, promote sustainability transparency, and align with global ESG reporting trends.', 'These regulations, which came into force on April 1, 2019, amend UK company law to enhance corporate energy and carbon reporting requirements. They introduce mandatory energy consumption and emissions disclosures for certain companies and limited liability partnerships (LLPs), aligning with climate and sustainability objectives.

