INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffcbbee1-dce6-5710-8a7c-ce890a885de6', 'UK Corporate Governance Code', 'The UK Corporate Governance Code, 2018', 'The 2018 revision applies to accounting periods beginning on or after 1 January 2019. It places greater emphasis on relationships between companies, shareholders and stakeholders. It also promotes the importance of establishing a corporate culture that is aligned with the company purpose, business strategy, promotes integrity and values diversity. The Code focusses on the application of the Principles and reporting on outcomes achieved. For the Code''s Provisions, companies should disclose how they have complied with these or provide an explanation appropriate to their individual circumstances.', 'The 2018 revision applies to accounting periods beginning on or after 1 January 2019. It places greater emphasis on relationships between companies, shareholders and stakeholders. It also promotes the importance of establishing a corporate culture that is aligned with the company purpose, business strategy, promotes integrity and values diversity. The Code focusses on the application of the Principles and reporting on outcomes achieved. For the Code''s Provisions, companies should disclose how they have complied with these or provide an explanation appropriate to their individual circumstances.', 'The 2018 revision applies to accounting periods beginning on or after 1 January 2019. It places greater emphasis on relationships between companies, shareholders and stakeholders. It also promotes the importance of establishing a corporate culture that is aligned with the company purpose, business strategy, promotes integrity and values diversity. The Code focusses on the application of the Principles and reporting on outcomes achieved. For the Code''s Provisions, companies should disclose how they have complied with these or provide an explanation appropriate to their individual circumstances.', 'UK', 'climate', 'in_force', '2018-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_65', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8580c2b-b61e-5a44-a2ca-e3e2b796ea87', 'UK Corporate Governance Code', 'UK Corporate Governance Code', 'The UK Corporate Governance Code 2024, issued by the Financial Reporting Council (FRC), sets out principles and provisions for corporate governance in publicly listed companies. It promotes board accountability, transparency, risk management, and ethical business practices to enhance long-term shareholder and stakeholder value. The 2024 revision focuses on strengthening internal controls, improving governance reporting, and ensuring better accountability for corporate sustainability.

Key provisions include:

Board Leadership & Purpose:
The board must define and implement corporate purpose, values, and strategy.
Engagement with shareholders and wider stakeholders is required.
Division of Responsibilities:
The Chair and CEO roles must be separate to ensure governance independence.
At least 50% of the board (excluding the Chair) must be independent non-executive directors.
Board Composition & Evaluation:
Companies must ensure board diversity and succession planning.
Annual board effectiveness evaluations are mandatory, with external reviews every three years for FTSE 350 firms.
Audit, Risk & Internal Control:
Boards must assess and disclose principal risks, ensuring robust internal controls.
Companies must declare the effectiveness of their financial and operational controls.
Strengthened audit committee responsibilities, including review of non-financial disclosures.
Executive Remuneration & Incentives:
Executive pay must align with company performance and long-term sustainability goals.
Clawback provisions must be included in remuneration policies to recover bonuses if misconduct or poor performance occurs.
‘Comply or Explain’ Approach:
Companies must either comply with the Code’s provisions or provide clear explanations for non-compliance in their annual reports.
The 2024 revision strengthens internal control accountability (Provision 29) but allows companies until January 1, 2026, to comply with new reporting requirements.', 'The UK Corporate Governance Code 2024, issued by the Financial Reporting Council (FRC), sets out principles and provisions for corporate governance in publicly listed companies. It promotes board accountability, transparency, risk management, and ethical business practices to enhance long-term shareholder and stakeholder value. The 2024 revision focuses on strengthening internal controls, improving governance reporting, and ensuring better accountability for corporate sustainability.

