INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b4d704d1-acd4-5f99-84ce-f67514fe66e5', 'UK Scottish Code of Good Higher Education Governance (2017', 'Scottish Code of Good Higher Education Governance (2017 edition)', 'This Code is concerned with governance of the institution and is organised into sections thematically. Each section starts with the high-level principles of good governance in the relevant area. More detailed provisions follow in the subsequent paragraphs.', 'This Code is concerned with governance of the institution and is organised into sections thematically. Each section starts with the high-level principles of good governance in the relevant area. More detailed provisions follow in the subsequent paragraphs.', 'This Code is concerned with governance of the institution and is organised into sections thematically. Each section starts with the high-level principles of good governance in the relevant area. More detailed provisions follow in the subsequent paragraphs.', 'UK', 'governance', 'in_force', '2017-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_55', ARRAY['sdg4', 'guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('61e171f0-9aa3-5569-bf7b-bd0d9affd67d', 'UK International Standard on Auditing (UK) 250 (Revised)', 'International Standard on Auditing (UK) 250 (Revised), 2017', 'The objectives of the auditor are: (a) To obtain sufficient appropriate audit evidence regarding compliance with the provisions of those laws and regulations generally recognized to have a direct effect on the determination of material amounts and disclosures in the financial statements; (b) To perform specified audit procedures to help identify instances of noncompliance with other laws and regulations that may have a material effect on the financial statements; and (c) To respond appropriately to identified or suspected non-compliance with laws and regulations identified during the audit.', 'The objectives of the auditor are: (a) To obtain sufficient appropriate audit evidence regarding compliance with the provisions of those laws and regulations generally recognized to have a direct effect on the determination of material amounts and disclosures in the financial statements; (b) To perform specified audit procedures to help identify instances of noncompliance with other laws and regulations that may have a material effect on the financial statements; and (c) To respond appropriately to identified or suspected non-compliance with laws and regulations identified during the audit.', 'The objectives of the auditor are: (a) To obtain sufficient appropriate audit evidence regarding compliance with the provisions of those laws and regulations generally recognized to have a direct effect on the determination of material amounts and disclosures in the financial statements; (b) To perform specified audit procedures to help identify instances of noncompliance with other laws and regulations that may have a material effect on the financial statements; and (c) To respond appropriately to identified or suspected non-compliance with laws and regulations identified during the audit.', 'UK', 'climate', 'in_force', '2017-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_68', ARRAY['voluntary_frameworks', 'uk', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('de96ed38-b22d-53d5-b352-f330debb39c2', 'UK Criminal Finances Act', 'Criminal Finances Act 2017', 'The Act amends the Proceeds of Crime Act 2002; make provision in connection with terrorist property; create corporate offences for cases where a person associated with a body corporate or partnership facilitates the commission by another person of a tax evasion offence; and for connected purposes. It received Royal Assent on April 27 2017.', 'The Act amends the Proceeds of Crime Act 2002; make provision in connection with terrorist property; create corporate offences for cases where a person associated with a body corporate or partnership facilitates the commission by another person of a tax evasion offence; and for connected purposes. It received Royal Assent on April 27 2017.', 'The Act amends the Proceeds of Crime Act 2002; make provision in connection with terrorist property; create corporate offences for cases where a person associated with a body corporate or partnership facilitates the commission by another person of a tax evasion offence; and for connected purposes. It received Royal Assent on April 27 2017.', 'UK', 'governance', 'in_force', '2017-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_69', ARRAY['uk', 'sdg17', 'regulations', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4700cd42-96e4-54a0-974e-b7059a646b18', 'UK Equality Act 2010 (Specific Duties and Public Authorities)', 'The Equality Act 2010 (Specific Duties and Public Authorities) Regulations 2017', 'This document includes Amendments to 2010 Equality Act. Employers will have to disclose the overall gender gap figures using a median and mean calculation, and will be required to report on the number of men and women working within salary quartiles.', 'This document includes Amendments to 2010 Equality Act. Employers will have to disclose the overall gender gap figures using a median and mean calculation, and will be required to report on the number of men and women working within salary quartiles.', 'This document includes Amendments to 2010 Equality Act. Employers will have to disclose the overall gender gap figures using a median and mean calculation, and will be required to report on the number of men and women working within salary quartiles.', 'UK', 'climate', 'in_force', '2017-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_71', ARRAY['uk', 'regulations', 'mandatory', 'sdg5', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7cd188e6-d116-5d51-9898-d719c236c2b8', 'UK Corporate governance in central government departments: Code', 'Corporate governance in central government departments: Code of good practice, 2017', 'Boards help departments and government succeed in achieving their aims by encouraging good planning, managing performance regularly and raising delivery capability. They also help foster a culture of openness and good governance by providing a clear oversight structure. The code provides for a ‘comply or explain’ approach, whereby a department can depart from the code’s provisions provided the reasons are explained in its annual governance statement accompanying the department’s accounts. The principles outlined in the code will also prove useful for other parts of central government and they are encouraged to apply arrangements suitably adapted for their organisation. The 2017 versions of the code and accompanying guidance update the previous 2011 editions.', 'Boards help departments and government succeed in achieving their aims by encouraging good planning, managing performance regularly and raising delivery capability. They also help foster a culture of openness and good governance by providing a clear oversight structure. The code provides for a ‘comply or explain’ approach, whereby a department can depart from the code’s provisions provided the reasons are explained in its annual governance statement accompanying the department’s accounts. The principles outlined in the code will also prove useful for other parts of central government and they are encouraged to apply arrangements suitably adapted for their organisation. The 2017 versions of the code and accompanying guidance update the previous 2011 editions.', 'Boards help departments and government succeed in achieving their aims by encouraging good planning, managing performance regularly and raising delivery capability. They also help foster a culture of openness and good governance by providing a clear oversight structure. The code provides for a ‘comply or explain’ approach, whereby a department can depart from the code’s provisions provided the reasons are explained in its annual governance statement accompanying the department’s accounts. The principles outlined in the code will also prove useful for other parts of central government and they are encouraged to apply arrangements suitably adapted for their organisation. The 2017 versions of the code and accompanying guidance update the previous 2011 editions.', 'UK', 'governance', 'in_force', '2017-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_99', ARRAY['other sustainability policy', 'uk', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d936b3f0-a2f2-597d-81a5-4428bb522971', 'UK AIC Code of Corporate Governance. Incorporating the UK', 'The AIC Code of Corporate Governance. Incorporating the UK Corporate Governance Code and the AIC Code of Corporate Governance, 2016', 'The AIC''s Corporate Governance Guide brings together the relevant requirements of the UK Corporate Governance Code and the AIC Code of Corporate Governance.', 'The AIC''s Corporate Governance Guide brings together the relevant requirements of the UK Corporate Governance Code and the AIC Code of Corporate Governance.', 'The AIC''s Corporate Governance Guide brings together the relevant requirements of the UK Corporate Governance Code and the AIC Code of Corporate Governance.', 'UK', 'governance', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_100', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('27a79d3a-9fb6-590f-b5cb-e44f9251b111', 'UK Companies, Partnerships and Groups (Accounts and Non-Financial Reporting)', 'The Companies, Partnerships and Groups (Accounts and Non-Financial Reporting) Regulations 2016', 'The regulation will require relevant companies to prepare a non-financial information statement as part of their strategic report covering a number of human rights issues.', 'The regulation will require relevant companies to prepare a non-financial information statement as part of their strategic report covering a number of human rights issues.', 'The regulation will require relevant companies to prepare a non-financial information statement as part of their strategic report covering a number of human rights issues.', 'UK', 'climate', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_18', ARRAY['uk', 'sdg17', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1133cd38-01d6-504d-8e2b-f140b9647f65', 'UK Companies, Partnerships and Groups (Accounts and Non-Financial Reporting)', 'Companies, Partnerships and Groups (Accounts and Non-Financial Reporting) Regulations', 'These UK regulations amend the Companies Act 2006 to implement the EU Non-Financial Reporting Directive (2014/95/EU), requiring certain large businesses to disclose non-financial and diversity information. The law enhances corporate transparency and ESG (Environmental, Social, and Governance) reporting by mandating disclosures on environmental, social, human rights, and anti-corruption matters.

Key provisions include:

Scope of Companies Covered:
Publicly traded companies, banks, and insurers.
Large companies with more than 500 employees.
Non-Financial Information Statement (NFIS) Requirements:
Disclosure of environmental impact, employee policies, social responsibility, human rights, and anti-bribery measures.
Explanation of due diligence processes and business model alignment with ESG risks.
Companies must explain if they do not pursue policies on these matters ("comply or explain" approach).
Strategic Report Amendments:
Companies must integrate ESG disclosures into their strategic reports.
ESG-related key performance indicators (KPIs) must be disclosed.
Group-Level Disclosures:
Parent companies must publish consolidated ESG reports covering all subsidiaries.
Alignment with International Reporting Standards:
Companies can use GRI, UN Global Compact, and other recognized frameworks.
These regulations strengthen corporate sustainability reporting, promote ESG accountability, and align UK law with EU and international disclosure standards.', 'These UK regulations amend the Companies Act 2006 to implement the EU Non-Financial Reporting Directive (2014/95/EU), requiring certain large businesses to disclose non-financial and diversity information. The law enhances corporate transparency and ESG (Environmental, Social, and Governance) reporting by mandating disclosures on environmental, social, human rights, and anti-corruption matters.

