INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5d7a1af8-e15d-589b-bf2b-c00e533128f2', 'UK Code of practice no: 13. Governance and administration', 'Code of practice no: 13. Governance and administration of occupational trust-based schemes providing money purchase benefits', 'This code of practice sets out the standards of conduct and practice that we expect trustee boards of occupational pension schemes providing money purchase benefits to meet to comply with their legal duties.', 'This code of practice sets out the standards of conduct and practice that we expect trustee boards of occupational pension schemes providing money purchase benefits to meet to comply with their legal duties.', 'This code of practice sets out the standards of conduct and practice that we expect trustee boards of occupational pension schemes providing money purchase benefits to meet to comply with their legal duties.', 'UK', 'social', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_26', ARRAY['sdg8', 'uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4024b65f-e41c-5bb0-bd0f-dc7ea014839e', 'UK Audit firm Governance Code. Revised', 'Audit firm Governance Code. Revised 2016', 'Audit is a statutory function in which there is considerable public interest. The UK Audit Firm Governance Code (the Code) is intended to enhance trust and confidence in the value of audit amongst the public and particularly investors. The Code applies to firms auditing 20 or more listed companies.', 'Audit is a statutory function in which there is considerable public interest. The UK Audit Firm Governance Code (the Code) is intended to enhance trust and confidence in the value of audit amongst the public and particularly investors. The Code applies to firms auditing 20 or more listed companies.', 'Audit is a statutory function in which there is considerable public interest. The UK Audit Firm Governance Code (the Code) is intended to enhance trust and confidence in the value of audit amongst the public and particularly investors. The Code applies to firms auditing 20 or more listed companies.', 'UK', 'climate', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_35', ARRAY['uk', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8b673026-cefa-5e26-bb8b-ee81659180f5', 'UK Takeover Code', 'The Takeover Code, 2016', 'Known as the City Code, the Takeover Code or the Blue Book. A set of statutory rules and general principles in relation to all offers and other transactions to which the Code applies. The Code rules and general principles regulate the conduct of UK public takeovers.', 'Known as the City Code, the Takeover Code or the Blue Book. A set of statutory rules and general principles in relation to all offers and other transactions to which the Code applies. The Code rules and general principles regulate the conduct of UK public takeovers.', 'Known as the City Code, the Takeover Code or the Blue Book. A set of statutory rules and general principles in relation to all offers and other transactions to which the Code applies. The Code rules and general principles regulate the conduct of UK public takeovers.', 'UK', 'governance', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_39', ARRAY['disclosure', 'mandatory', 'uk', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('48cc16c2-7008-51ac-aa94-c665183e4253', 'UK Corporate Governance Guide for Investment Companies. Incorporating the', 'Corporate Governance Guide for Investment Companies. Incorporating the UK Corporate Governance Code and the AIC Code of Corporate Governance, 2016', 'The AIC Corporate Governance Guide for Investment Companies (AIC Guide) brings together the recommendations of the UK Corporate Governance Code (UK Code) and the AIC Code of Corporate Governance (AIC Code) into a single document and demonstrates how the AIC Code translates each principle of the UK Code into principles and recommendations suitable to the industry’s unique structure.', 'The AIC Corporate Governance Guide for Investment Companies (AIC Guide) brings together the recommendations of the UK Corporate Governance Code (UK Code) and the AIC Code of Corporate Governance (AIC Code) into a single document and demonstrates how the AIC Code translates each principle of the UK Code into principles and recommendations suitable to the industry’s unique structure.', 'The AIC Corporate Governance Guide for Investment Companies (AIC Guide) brings together the recommendations of the UK Corporate Governance Code (UK Code) and the AIC Code of Corporate Governance (AIC Code) into a single document and demonstrates how the AIC Code translates each principle of the UK Code into principles and recommendations suitable to the industry’s unique structure.', 'UK', 'governance', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_57', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4f7618c0-f615-5366-b1b6-a0969e918251', 'UK Corporate Governance Code', 'The UK Corporate Governance Code, 2016', 'The Code is a guide to a number of key components of effective board practice. It is based on the underlying principles of all good governance: accountability, transparency, probity and focus on the sustainable success of an entity over the longer term.', 'The Code is a guide to a number of key components of effective board practice. It is based on the underlying principles of all good governance: accountability, transparency, probity and focus on the sustainable success of an entity over the longer term.', 'The Code is a guide to a number of key components of effective board practice. It is based on the underlying principles of all good governance: accountability, transparency, probity and focus on the sustainable success of an entity over the longer term.', 'UK', 'climate', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_67', ARRAY['uk', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e4c9040e-67ce-55bb-b3df-1c80996e855b', 'UK AIC Code of Corporate Governance. A framework', 'The AIC Code of Corporate Governance. A framework of best practice for member companies, 2016', 'The AIC Code of Corporate Governance sets out a framework of best practice in respect of the governance of investment companies. It has been endorsed by the Financial Reporting Council as an alternative means for our members to meet their obligations in relation to the UK Corporate Governance Code.', 'The AIC Code of Corporate Governance sets out a framework of best practice in respect of the governance of investment companies. It has been endorsed by the Financial Reporting Council as an alternative means for our members to meet their obligations in relation to the UK Corporate Governance Code.', 'The AIC Code of Corporate Governance sets out a framework of best practice in respect of the governance of investment companies. It has been endorsed by the Financial Reporting Council as an alternative means for our members to meet their obligations in relation to the UK Corporate Governance Code.', 'UK', 'climate', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_85', ARRAY['uk', 'regulations', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6092a0bf-54bd-528b-af89-ac9020b8d84c', 'UK Audit Committees', 'Guidance on Audit Committees, 2016', 'This guidance is designed to assist company boards in making suitable arrangements for their audit committees, and to assist directors serving on audit committees in carrying out their role. While boards are not required to follow this guidance, it is intended to assist them when implementing the relevant provisions of the UK Corporate Governance Code and should, in particular, be read in conjunction with section C.3 of the Code.', 'This guidance is designed to assist company boards in making suitable arrangements for their audit committees, and to assist directors serving on audit committees in carrying out their role. While boards are not required to follow this guidance, it is intended to assist them when implementing the relevant provisions of the UK Corporate Governance Code and should, in particular, be read in conjunction with section C.3 of the Code.', 'This guidance is designed to assist company boards in making suitable arrangements for their audit committees, and to assist directors serving on audit committees in carrying out their role. While boards are not required to follow this guidance, it is intended to assist them when implementing the relevant provisions of the UK Corporate Governance Code and should, in particular, be read in conjunction with section C.3 of the Code.', 'UK', 'climate', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_87', ARRAY['guidance_frameworks', 'uk', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('39defb76-1ee8-57de-9aac-305b52627d9e', 'UK Good Business: Implementing the UN Guiding Principles', 'Good Business: Implementing the UN Guiding Principles on Business and Human Rights. Updated May 2016', 'The update of the UK’s National Action Plan on Business and Human Rights was published on the 12 May 2016 and reflects the broad range of activity and engagement which takes place across a large number of government departments. This update reaffirms the UK’s commitment to the implementation of the United Nations Guiding Principles (UNGP) on Business and Human Rights, and acknowledges the duty of government but also sets out our expectation that UK businesses will act responsibly and in accordance with the UNGPs, wherever they operate.', 'The update of the UK’s National Action Plan on Business and Human Rights was published on the 12 May 2016 and reflects the broad range of activity and engagement which takes place across a large number of government departments. This update reaffirms the UK’s commitment to the implementation of the United Nations Guiding Principles (UNGP) on Business and Human Rights, and acknowledges the duty of government but also sets out our expectation that UK businesses will act responsibly and in accordance with the UNGPs, wherever they operate.', 'The update of the UK’s National Action Plan on Business and Human Rights was published on the 12 May 2016 and reflects the broad range of activity and engagement which takes place across a large number of government departments. This update reaffirms the UK’s commitment to the implementation of the United Nations Guiding Principles (UNGP) on Business and Human Rights, and acknowledges the duty of government but also sets out our expectation that UK businesses will act responsibly and in accordance with the UNGPs, wherever they operate.', 'UK', 'governance', 'in_force', '2016-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_9', ARRAY['guidance_frameworks', 'uk', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3bda9c3b-ffa1-5444-b91d-454e0140a137', 'Well-being of Future Generations (Wales) Bill', 'Well-being of Future Generations (Wales) Bill, 2015', 'The Act focuses on the future development of Wales (“The Wales we want by 2050”) and the role of public bodies in particular. Among other things, the Bill will introduce a reporting requirement for the public sector.', 'The Act focuses on the future development of Wales (“The Wales we want by 2050”) and the role of public bodies in particular. Among other things, the Bill will introduce a reporting requirement for the public sector.', 'The Act focuses on the future development of Wales (“The Wales we want by 2050”) and the role of public bodies in particular. Among other things, the Bill will introduce a reporting requirement for the public sector.', 'UK', 'climate', 'in_force', '2015-01-01'::date, 'United Kingdom', 'https://www.carrotsandsticks.org/policies/184_13', ARRAY['uk', 'regulations', 'mandatory', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
